// Ticks its own `now` internally instead of taking it as a prop fed by a top-level
// setInterval - it used to be state on the whole PublicSite component, which meant
// the ENTIRE page (hundreds of ledger entries, every pricing card, everything)
// fully re-rendered once a second forever just to redraw this one small icon. Moon
// phase also doesn't visibly change within an hour, let alone a second, so the tick
// is slowed to a minute here too - purely a bonus, the isolation is the real fix.
// Found + fixed 2026-07-31 during a performance audit.
function MoonPhase() {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 60_000)
    return () => clearInterval(t)
  }, [])
  const KNOWN_NEW_MOON = 947182440000 // 2000-01-06T18:14:00Z
  const SYNODIC_MS = 29.53059 * 86400 * 1000
  const phase = ((now - KNOWN_NEW_MOON) % SYNODIC_MS + SYNODIC_MS) % SYNODIC_MS / SYNODIC_MS
  const r = 9, cx = 11, cy = 11
  let fill: React.ReactNode = null
  if (phase >= 0.02 && phase <= 0.98) {
    // terminator = half-ellipse; rx shrinks to 0 at the quarters, = r at full.
    const a = 2 * Math.PI * phase
    const rx = Math.max(0.01, Math.abs(Math.cos(a)) * r)
    const waxing = phase < 0.5                       // lit limb on the right while waxing
    const gibbous = phase > 0.25 && phase < 0.75     // >50% illuminated
    const outerSweep = waxing ? 1 : 0                // the always-lit semicircle
    const termSweep = gibbous ? outerSweep : 1 - outerSweep
    const d = `M ${cx} ${cy - r} A ${r} ${r} 0 0 ${outerSweep} ${cx} ${cy + r} A ${rx} ${r} 0 0 ${termSweep} ${cx} ${cy - r}`
    fill = <path d={d} fill="#f0ead8" />
  }
  return (
    <svg width="22" height="22" viewBox="0 0 22 22" fill="none" style={{ display: 'block' }}>
      <circle cx={cx} cy={cy} r={r} fill="#06061a" />
      {fill}
      <circle cx={cx} cy={cy} r={r} fill="none" stroke="rgba(255,255,255,0.13)" strokeWidth="0.5" />
    </svg>
  )
}


function LedgerDropdown({ id, value, onSelect, options, placeholder, selColor, open, onToggle, minWidth, mobile }: {
  id: string
  value: string
  onSelect: (v: string) => void
  options: { value: string; label: string; color?: string }[]
  placeholder: string
  selColor: string | null
  open: boolean
  onToggle: (id: string | null) => void
  minWidth: number
  mobile: boolean
}) {
  const active = !!value && value !== 'default'
  const accent = active ? (selColor || '#00f5c4') : null
  const current = options.find(o => o.value === value)
  return (
    <div style={{ position: 'relative', ...(mobile ? { flex: 1 } : { flexShrink: 0 }) }}>
      <button onClick={() => onToggle(open ? null : id)} style={{
        height: '100%', boxSizing: 'border-box', width: mobile ? '100%' : undefined, minWidth: mobile ? undefined : minWidth,
        display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8,
        background: active ? 'rgba(0,245,196,0.07)' : 'rgba(0,245,196,0.04)',
        border: `1px solid ${active ? (accent as string) : 'rgba(0,245,196,0.18)'}`,
        borderRadius: 7, padding: '11px 12px',
        color: active ? (accent as string) : 'var(--text3)',
        fontFamily: "'JetBrains Mono', monospace", fontSize: 10, fontWeight: 700, letterSpacing: '0.08em',
        cursor: 'pointer', outline: 'none',
      }}>
        <span style={{ whiteSpace: 'nowrap' }}>{current ? current.label : placeholder}</span>
        <svg width="9" height="9" viewBox="0 0 9 9" fill="none" stroke={active ? (accent as string) : 'rgba(0,245,196,0.5)'}
          style={{ transition: 'transform 0.2s', transform: open ? 'rotate(180deg)' : 'none', flexShrink: 0 }}>
          <path d="M1.5 3L4.5 6L7.5 3" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </button>
      {open && (
        <>
          <div onClick={() => onToggle(null)} style={{ position: 'fixed', inset: 0, zIndex: 40 }} />
          <div className="ledger-dd-panel" data-native-scroll style={{
            position: 'absolute', top: 'calc(100% + 4px)', left: 0, zIndex: 41,
            minWidth: mobile ? '100%' : Math.max(minWidth, 150), maxHeight: 300, overflowY: 'auto',
            background: '#0c1120', border: '1px solid rgba(0,245,196,0.25)', borderRadius: 8,
            boxShadow: '0 12px 32px rgba(0,0,0,0.6)', padding: 4,
            animation: 'ddIn 0.16s cubic-bezier(0.22,1,0.36,1)',
          }}>
            {options.map(o => {
              const sel = o.value === value
              return (
                <div key={o.value || '_'} className="ledger-dd-opt"
                  onClick={() => { onSelect(o.value); onToggle(null) }}
                  style={{
                    padding: '8px 12px', borderRadius: 5, cursor: 'pointer',
                    fontFamily: "'JetBrains Mono', monospace", fontSize: 10, fontWeight: 700, letterSpacing: '0.06em',
                    color: sel ? (o.color || '#00f5c4') : 'var(--text2)',
                    background: sel ? 'rgba(0,245,196,0.10)' : 'transparent',
                  }}>
                  {o.label}
                </div>
              )
            })}
          </div>
        </>
      )}
    </div>
  )
}


// TRACK RECORD - the permanent disclosure ledger (search + filter + table).
// KPIs live ABOVE the panel as their own clean row. Filter/sort/search state and
// the report-PDF modal are owned by PublicSite.tsx (the modal is shared chrome,
// same layer as the checkout/proposal modals) and passed in as props.
export function TrackRecordSection({
  mobile, theme, now, ledgerFired, ledgerRef,
  searchQuery, setSearchQuery, activeStatus, setActiveStatus, activeSev, setActiveSev,
  sortBy, setSortBy, openDD, setOpenDD, setReportModal, setIntelModal,
}: {
  mobile: boolean
  theme: Theme
  now: number
  ledgerFired: boolean
  ledgerRef: React.RefObject<HTMLDivElement | null>
  searchQuery: string
  setSearchQuery: (v: string) => void
  activeStatus: string | null
  setActiveStatus: (v: string | null) => void
  activeSev: string | null
  setActiveSev: (v: string | null) => void
  sortBy: string
  setSortBy: (v: string) => void
  openDD: string | null
  setOpenDD: (v: string | null) => void
  setReportModal: (v: string) => void
  setIntelModal: (v: { target: string; market: string; sev: string; finding: string; headline?: string } | null) => void
}) {
  const { t, locale } = useLocale()
  return (
    <section id="track-record" style={{ padding: '48px 2rem 72px' }}>
      <div style={{ maxWidth: 1320, margin: '0 auto' }}>
        <Reveal from="left">
          <p style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: 'var(--text3)', textTransform: 'uppercase', letterSpacing: '0.2em', marginBottom: 12 }}>{t.trackRecord.eyebrow}</p>
          <h2 style={{ fontSize: 32, fontWeight: 900, marginBottom: 12 }}><ScrambleHeading text={t.trackRecord.heading} /></h2>
        </Reveal>
        <Reveal from="right" delay={1}>
          {/* Solid backing added 2026-08-06 (spine feedback): this paragraph sits
              directly on the page background with nothing behind it, and its
              720px max-width crosses the page's horizontal center where the
              spine/orb live. Padding + a matching negative margin keep the text
              itself pixel-aligned with before - only the panel is new. */}
          <p style={{
            color: 'var(--text2)', marginBottom: 40, maxWidth: 720, fontSize: 15, lineHeight: 1.9,
            background: 'var(--glass-bg-solid)', borderRadius: 8, padding: '8px 12px', marginLeft: -12, marginTop: -8,
          }}>
            {t.trackRecord.paragraph}
          </p>
        </Reveal>
        {/* Permanent disclosure ledger — framed panel (search + table).
            KPIs live ABOVE the panel as their own clean row now. */}
        {/* KPI numbers + labels live OUTSIDE any box (free row). */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 16, marginBottom: 20 }}>
          {[
            { n: `${AUDIT_HIGHLIGHTS.length}+`, label: t.trackRecord.kpis.appsAudited,          sub: t.trackRecord.kpisSub.appsAudited,        from: 'left'   },
            { n: `1.08M`,                    label: t.trackRecord.kpis.smaliClasses,           sub: t.trackRecord.kpisSub.smaliClasses,     from: 'bottom' },
            { n: `${AUDIT_HIGHLIGHTS.filter(a => a.sev === 'CRITICAL').length}+`, label: t.trackRecord.kpis.criticalFindings, sub: t.trackRecord.kpisSub.criticalFindings, from: 'top' },
            { n: `499`,                      label: t.trackRecord.kpis.trackersFound,          sub: t.trackRecord.kpisSub.trackersFound,    from: 'right'  },
            { n: `392`,                      label: t.trackRecord.kpis.endpointsInvestigated,  sub: t.trackRecord.kpisSub.endpointsInvestigated, from: 'left' },
            { n: `192`,                      label: t.trackRecord.kpis.sdkClasses,             sub: t.trackRecord.kpisSub.sdkClasses,       from: 'bottom' },
          ].map((s, i) => (
            <Reveal key={s.label} delay={i} from={s.from as 'left'|'bottom'|'top'|'right'}>
              <div style={{ textAlign: 'center' }}>
                <div style={{ fontSize: 44, fontWeight: 900, color: 'var(--accent-text)', lineHeight: 1, letterSpacing: '-0.02em' }}><CountUp value={s.n} /></div>
                <div style={{ fontSize: 12, color: 'var(--text)', fontWeight: 700, fontFamily: "'JetBrains Mono', monospace", textTransform: 'uppercase', letterSpacing: '0.14em', marginTop: 10 }}>{s.label}</div>
              </div>
            </Reveal>
          ))}
        </div>

        {/* Single box holding ONLY the KPI descriptions. */}
        <div style={{
          background: theme === 'dark'
            ? 'linear-gradient(155deg, #1e1e24 0%, #101013 30%, #0a0a0c 55%, #17171d 78%, #0c0c0f 100%), repeating-linear-gradient(112deg, rgba(255,255,255,0.05) 0px, rgba(255,255,255,0.05) 1px, transparent 1px, transparent 3px)'
            : 'var(--bg2)',
          backgroundBlendMode: theme === 'dark' ? 'overlay' : 'normal',
          border: theme === 'dark' ? '1px solid rgba(0,245,196,0.35)' : '1px solid rgba(10,122,92,0.45)',
          borderRadius: 12, padding: '18px 22px', marginBottom: 28,
          boxShadow: theme === 'dark'
            ? 'inset 0 1px 0 rgba(255,255,255,0.07), inset 0 0 40px rgba(0,0,0,0.4), 0 8px 32px rgba(0,0,0,0.5)'
            : '0 8px 32px rgba(0,0,0,0.35)',
        }}>
          {[
            { n: `${AUDIT_HIGHLIGHTS.length}+`, label: t.trackRecord.kpis.appsAudited,          sub: t.trackRecord.kpisSub.appsAudited },
            { n: `1.08M`,                    label: t.trackRecord.kpis.smaliClasses,           sub: t.trackRecord.kpisSub.smaliClasses },
            { n: `${AUDIT_HIGHLIGHTS.filter(a => a.sev === 'CRITICAL').length}+`, label: t.trackRecord.kpis.criticalFindings, sub: t.trackRecord.kpisSub.criticalFindings },
            { n: `499`,                      label: t.trackRecord.kpis.trackersFound,          sub: t.trackRecord.kpisSub.trackersFound },
            { n: `392`,                      label: t.trackRecord.kpis.endpointsInvestigated,  sub: t.trackRecord.kpisSub.endpointsInvestigated },
            { n: `192`,                      label: t.trackRecord.kpis.sdkClasses,             sub: t.trackRecord.kpisSub.sdkClasses },
          ].map((s, i) => (
            <div key={s.label} style={{ display: 'flex', gap: 12, alignItems: 'baseline', padding: '7px 0', borderBottom: i < 5 ? '1px solid rgba(255,255,255,0.06)' : 'none' }}>
              <span style={{ flex: '0 0 130px', fontSize: 12, fontWeight: 800, color: 'var(--accent-text)', fontFamily: "'JetBrains Mono', monospace", textTransform: 'uppercase', letterSpacing: '0.08em' }}>{s.n} {s.label}</span>
              <span style={{ flex: 1, fontSize: 12, color: 'var(--text2)', lineHeight: 1.4 }}>{s.sub}</span>
            </div>
          ))}
        </div>

        {/* Solid background added 2026-08-06 (spine feedback: the panel had none at
            all, just a border, so the scroll spine/orb bled straight through the
            search bar, dropdowns, and every table row underneath it). */}
        <div style={{ background: 'var(--glass-bg-solid)', border: '1px solid var(--accent-text)', borderRadius: 12, padding: '18px 20px 16px', marginBottom: 32 }}>
        <div style={{ display: 'flex', gap: 8, marginBottom: 8, alignItems: 'stretch', flexWrap: mobile ? 'wrap' : 'nowrap' }}>

          {/* Search */}
          <div style={{ position: 'relative', flex: 1, minWidth: 0, ...(mobile ? { flexBasis: '100%' } : {}) }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="rgba(0,245,196,0.5)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"
              style={{ position: 'absolute', left: 14, top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none' }}>
              <circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
            </svg>
            <input
              type="text"
              placeholder={t.trackRecord.searchPlaceholder}
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              style={{
                width: '100%', boxSizing: 'border-box',
                background: 'rgba(0,245,196,0.04)',
                border: searchQuery ? '1px solid rgba(0,245,196,0.55)' : '1px solid rgba(0,245,196,0.18)',
                borderRadius: 7, padding: '13px 38px 13px 46px',
                color: 'var(--text)', fontFamily: 'Inter, system-ui, sans-serif', fontSize: 13,
                outline: 'none', transition: 'border-color 0.15s',
              }}
              onFocus={e => { e.currentTarget.style.borderColor = 'rgba(0,245,196,0.55)' }}
              onBlur={e => { if (!searchQuery) e.currentTarget.style.borderColor = 'rgba(0,245,196,0.18)' }}
            />
            {searchQuery && (
              <button onClick={() => setSearchQuery('')} style={{
                position: 'absolute', right: 12, top: '50%', transform: 'translateY(-50%)',
                background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text3)', padding: 4, lineHeight: 0,
              }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            )}
          </div>

          {/* Status dropdown */}
          <LedgerDropdown id="status" mobile={mobile} minWidth={115}
            value={activeStatus ?? ''} onSelect={v => setActiveStatus(v || null)}
            open={openDD === 'status'} onToggle={setOpenDD} placeholder={t.trackRecord.dropdowns.statusPlaceholder}
            selColor={activeStatus ? (STATUS_META[activeStatus]?.color ?? TEAL) : null}
            options={[{ value: '', label: t.trackRecord.dropdowns.statusPlaceholder }, ...Object.entries(STATUS_META).map(([k, v]) => ({ value: k, label: `${v.label} (${AUDIT_HIGHLIGHTS.filter(a => a.status === k).length})`, color: v.color }))]}
          />

          {/* SEV dropdown */}
          <LedgerDropdown id="sev" mobile={mobile} minWidth={88}
            value={activeSev ?? ''} onSelect={v => setActiveSev(v || null)}
            open={openDD === 'sev'} onToggle={setOpenDD} placeholder={t.trackRecord.dropdowns.sevPlaceholder}
            selColor={activeSev === 'CRITICAL' ? '#f87171' : activeSev === 'HIGH' ? '#fb923c' : activeSev === 'MEDIUM' ? '#fbbf24' : null}
            options={[{ value: '', label: t.trackRecord.dropdowns.sevPlaceholder }, ...(['CRITICAL', 'HIGH', 'MEDIUM'] as const).map(sev => ({ value: sev, label: `${sev} (${AUDIT_HIGHLIGHTS.filter(a => a.sev === sev).length})`, color: sev === 'CRITICAL' ? '#f87171' : sev === 'HIGH' ? '#fb923c' : '#fbbf24' }))]}
          />

          {/* Sort by dropdown */}
          <LedgerDropdown id="sort" mobile={mobile} minWidth={130}
            value={sortBy} onSelect={v => setSortBy(v)}
            open={openDD === 'sort'} onToggle={setOpenDD} placeholder={t.trackRecord.dropdowns.sortPlaceholder}
            selColor={sortBy !== 'default' ? TEAL : null}
            options={[
              { value: 'elapsed-desc', label: t.trackRecord.dropdowns.sortOptions.elapsedDesc },
              { value: 'notified-desc', label: t.trackRecord.dropdowns.sortOptions.notifiedDesc },
              { value: 'notified-asc', label: t.trackRecord.dropdowns.sortOptions.notifiedAsc },
              { value: 'sev', label: t.trackRecord.dropdowns.sortOptions.sev },
              { value: 'status', label: t.trackRecord.dropdowns.sortOptions.status },
              { value: 'default', label: t.trackRecord.dropdowns.sortOptions.default },
            ]}
          />

          {/* Moon */}
          <div style={{ flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 10px', border: '1px solid var(--border)', borderRadius: 7, background: 'rgba(255,255,255,0.02)' }}>
            <MoonPhase />
          </div>

        </div>
        {(searchQuery.trim() || activeStatus || activeSev || sortBy !== 'default') && (() => {
          const n = AUDIT_HIGHLIGHTS.filter(a =>
            (!searchQuery.trim() ||
              a.target.toLowerCase().includes(searchQuery.toLowerCase()) ||
              a.finding[locale].toLowerCase().includes(searchQuery.toLowerCase()) ||
              a.market.toLowerCase().includes(searchQuery.toLowerCase()) ||
              (a.aliases ?? []).some(al => al.toLowerCase().includes(searchQuery.toLowerCase()))
            ) &&
            (!activeStatus || a.status === activeStatus) &&
            (!activeSev || a.sev === activeSev)
          ).length
          const sortLabel = t.trackRecord.resultsSummary.sortLabel
          return (
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: n > 0 ? TEAL : '#f87171', marginBottom: 10, letterSpacing: '0.06em' }}>
              {n > 0 ? t.trackRecord.resultsSummary.matches(n, AUDIT_HIGHLIGHTS.length) : t.trackRecord.resultsSummary.noMatches}
              {searchQuery.trim() ? t.trackRecord.resultsSummary.forQuery(searchQuery) : ''}
              {sortBy !== 'default' ? t.trackRecord.resultsSummary.sortedBy(sortLabel[sortBy] ?? sortBy) : ''}
            </div>
          )
        })()}

        {/* Table */}
        <div data-native-scroll style={{ maxHeight: mobile ? '65vh' : 900, overflowY: 'auto', borderRadius: 8, scrollbarWidth: 'thin', scrollbarColor: 'rgba(0,245,196,0.2) transparent', border: '1px solid var(--border2)' }}>
          <style>{`@keyframes ledgerRowIn{from{opacity:0;transform:translateX(-20px)}to{opacity:1;transform:none}}.ledger-sel{color-scheme:dark}.ledger-sel option{background:#12121e;color:#e2e2f0}@keyframes ekgPulse{0%{stroke-dashoffset:150;opacity:0}5%{opacity:1}85%{opacity:1}100%{stroke-dashoffset:-150;opacity:0}}.ekg-line{stroke-dasharray:150;animation:ekgPulse 3.6s linear infinite}@keyframes ddIn{from{opacity:0;transform:translateY(-6px) scaleY(0.97)}to{opacity:1;transform:none}}.ledger-dd-panel{transform-origin:top}.ledger-dd-opt:hover{background:rgba(0,245,196,0.12)!important;color:#00f5c4!important}.intel-cell{border:1px solid transparent;border-radius:6px;margin:-6px -8px;padding:6px 8px;transition:border-color 80ms,background 80ms}.intel-cell:hover{border-color:rgba(0,245,196,0.35);background:rgba(0,245,196,0.05)}.intel-cell:hover .intel-hint{color:#00f5c4}.ledger-grid>*{border-right:1px solid var(--border2);padding-right:8px;min-width:0}.ledger-grid>*:last-child{border-right:none;padding-right:0}`}</style>

          {/* Sticky header */}
          <div className="ledger-grid" style={{
            display: 'grid',
            gridTemplateColumns: mobile
              ? '1fr 85px 110px'
              : 'minmax(120px,1.6fr) 82px 100px 72px minmax(160px,4fr) 110px 70px 130px 130px 56px',
            gap: '0 6px',
            padding: '7px 14px',
            position: 'sticky', top: 0, zIndex: 2,
            background: 'var(--bg)', borderBottom: '1px solid var(--border2)',
            fontFamily: "'JetBrains Mono', monospace", fontSize: 10, fontWeight: 700,
            color: 'var(--text)', textTransform: 'uppercase', letterSpacing: '0.1em',
          }}>
            <span>{t.trackRecord.table.organisation}</span>
            {!mobile && <span>{t.trackRecord.table.notified}</span>}
            <span style={{ textAlign: 'center' }}>{t.trackRecord.table.status}</span>
            {!mobile && <span style={{ textAlign: 'center' }}>{t.trackRecord.table.sev}</span>}
            {!mobile && <span>{t.trackRecord.table.intel} <span style={{ color: 'var(--text4)', fontWeight: 400, textTransform: 'none', letterSpacing: 'normal' }}>({t.trackRecord.table.intelClickHint})</span></span>}
            {!mobile && <span>{t.trackRecord.table.statutes}</span>}
            {!mobile && <span style={{ textAlign: 'center' }}>{t.trackRecord.table.resolved}</span>}
            <span>{t.trackRecord.table.disclosure}</span>
            {!mobile && <span>{t.trackRecord.table.elapsed}</span>}
            {!mobile && <span>{t.trackRecord.table.report}</span>}
          </div>

          {/* Rows */}
          <div ref={ledgerRef}>
            {AUDIT_HIGHLIGHTS.filter(a =>
              (!searchQuery.trim() ||
                a.target.toLowerCase().includes(searchQuery.toLowerCase()) ||
                a.finding[locale].toLowerCase().includes(searchQuery.toLowerCase()) ||
                a.market.toLowerCase().includes(searchQuery.toLowerCase()) ||
                (a.aliases ?? []).some(al => al.toLowerCase().includes(searchQuery.toLowerCase()))
              ) &&
              (!activeStatus || a.status === activeStatus) &&
              (!activeSev || a.sev === activeSev)
            ).sort((x, y) => {
              const SEV_ORDER: Record<string, number> = { CRITICAL: 0, HIGH: 1, MEDIUM: 2 }
              const STATUS_ORDER: Record<string, number> = { RESOLVED: -1, SILENT: 0, ESCALATED: 1, 'CS-DEFLECT': 2, REGULATOR: 2.5, WAITING: 3, ACK: 4, SUBSTANTIVE: 5, ENGAGED: 6, PAID: 7 }
              const resolveTs = (a: typeof x) => { const m = AUDIT_META[a.target]; if (m?.notified) return new Date(m.notified).getTime(); const d = a.finding[locale].match(/(\d{4}-\d{2}-\d{2})/); return d ? new Date(d[1]).getTime() : 0 }
              const notifiedX = resolveTs(x)
              const notifiedY = resolveTs(y)
              const elapsedX = notifiedX ? now - notifiedX : 0
              const elapsedY = notifiedY ? now - notifiedY : 0
              if (sortBy === 'elapsed-desc') return elapsedY - elapsedX
              if (sortBy === 'notified-desc') return notifiedY - notifiedX
              if (sortBy === 'notified-asc') return notifiedX - notifiedY
              if (sortBy === 'sev') return (SEV_ORDER[x.sev] ?? 9) - (SEV_ORDER[y.sev] ?? 9)
              if (sortBy === 'status') return (STATUS_ORDER[x.status] ?? 9) - (STATUS_ORDER[y.status] ?? 9)
              return 0
            }).map((a, i) => {
              const sm = STATUS_META[a.status] ?? STATUS_META['WAITING']
              const meta = AUDIT_META[a.target]
              const disclosureTs = meta ? new Date(meta.disclosure).getTime() : new Date('2026-09-19').getTime()
              const msLeft = Math.max(0, disclosureTs - now)
              const daysLeft = Math.floor(msLeft / 86400000)
              const hLeft  = Math.floor((msLeft % 86400000) / 3600000)
              const mLeft  = Math.floor((msLeft % 3600000) / 60000)
              const sLeft  = Math.floor((msLeft % 60000) / 1000)
              const pad = (n: number) => String(n).padStart(2, '0')
              const cdStr = `${daysLeft}d ${pad(hLeft)}h ${pad(mLeft)}m ${pad(sLeft)}s`
              const cdColor = daysLeft > 60 ? TEAL : daysLeft > 30 ? '#fb923c' : '#f87171'
              const delay = Math.min(i * 30, 1500)
              const resolved = meta?.resolved ?? false
              const notifiedTs = meta?.notified ? new Date(meta.notified).getTime() : (() => { const d = a.finding[locale].match(/(\d{4}-\d{2}-\d{2})/); return d ? new Date(d[1]).getTime() : null })()
              const resolvedTs = meta?.resolvedDate ? new Date(meta.resolvedDate).getTime() : null
              const elapsedEnd = (resolved && resolvedTs) ? resolvedTs : now
              const elapsedMs  = notifiedTs ? Math.max(0, elapsedEnd - notifiedTs) : 0
              const eDays = Math.floor(elapsedMs / 86400000)
              const eH    = Math.floor((elapsedMs % 86400000) / 3600000)
              const eM    = Math.floor((elapsedMs % 3600000)  / 60000)
              const eS    = Math.floor((elapsedMs % 60000)    / 1000)
              const eStr  = `${eDays}d ${pad(eH)}h ${pad(eM)}m ${pad(eS)}s`
              const eColor = resolved ? '#4ade80' : eDays > 60 ? '#f87171' : eDays > 30 ? '#fb923c' : TEAL
              const totalWindowMs = notifiedTs ? disclosureTs - notifiedTs : 90 * 86400000
              const batteryPct = notifiedTs ? Math.max(0, Math.min(1, (disclosureTs - now) / totalWindowMs)) : 1
              const batteryColor = batteryPct > 0.66 ? '#4ade80' : batteryPct > 0.33 ? '#fb923c' : '#f87171'
              return (
                <div key={i} className="intel-row ledger-grid" style={{
                  position: 'relative',
                  overflow: 'hidden',
                  display: 'grid',
                  gridTemplateColumns: mobile
                    ? '1fr 95px 82px'
                    : 'minmax(120px,1.6fr) 82px 100px 72px minmax(160px,4fr) 110px 70px 130px 130px 56px',
                  gap: '0 6px',
                  padding: '9px 14px',
                  alignItems: 'start',
                  borderBottom: '1px solid var(--border2)',
                  background: i % 2 === 0 ? 'var(--bg2)' : 'transparent',
                  opacity: ledgerFired ? undefined : 0,
                  animation: ledgerFired ? `ledgerRowIn 0.38s cubic-bezier(0.22,1,0.36,1) ${delay}ms both` : 'none',
                }}>
                  {/* Battery bar */}
                  <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 3, background: 'rgba(255,255,255,0.05)' }}>
                    <div style={{ height: '100%', width: '100%',
                      // scaleX, not width: this bar exists on all 311 ledger rows and is
                      // re-driven by a 1Hz clock tick. Animating width ran layout+paint on
                      // every row every second; transform is compositor-only.
                      transform: `scaleX(${resolved ? 1 : batteryPct})`, transformOrigin: '0 50%', background: resolved ? 'linear-gradient(90deg, rgba(0,245,196,0.55), #00f5c4)' : `linear-gradient(90deg, ${batteryColor}55, ${batteryColor})`, borderRadius: '0 2px 0 0', transition: 'transform 1s linear' }} />
                  </div>
                  {/* Organisation */}
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 12, color: 'var(--text)', lineHeight: 1.4 }}>{a.target}</div>
                    <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 9, color: 'var(--text3)', textTransform: 'uppercase', marginTop: 2 }}>{a.market}</div>
                  </div>

                  {/* Notified */}
                  {!mobile && (
                    <div style={{ paddingTop: 1 }}>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: meta?.notified ? 'var(--text2)' : 'var(--text4)' }}>
                        {meta?.notified ?? '-'}
                      </div>
                      {notifiedTs && (
                        <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 9, color: 'var(--accent-text)', marginTop: 2, letterSpacing: '0.04em' }}>
                          {eDays === 0 ? t.trackRecord.row.today : t.trackRecord.row.daysAgo(eDays)}
                        </div>
                      )}
                    </div>
                  )}

                  {/* Status */}
                  <div style={{ paddingTop: 1, textAlign: 'center' }}>
                    <span className="site-status-badge" style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 3, border: '1px solid var(--border)', background: sm.bg, color: sm.color, letterSpacing: '0.07em', whiteSpace: 'nowrap' }}>{sm.label}</span>
                  </div>

                  {/* SEV */}
                  {!mobile && (
                    <div style={{ paddingTop: 1, textAlign: 'center' }}>
                      <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 9, fontWeight: 700, color: SEV_COLOR[a.sev] ?? TEAL }}>{a.sev}</span>
                    </div>
                  )}

                  {/* Intel */}
                  {!mobile && (() => {
                    const sep = ' — meaning '
                    const findingText = a.finding[locale]
                    const si = findingText.indexOf(sep)
                    const technical = si === -1 ? findingText : findingText.slice(0, si)
                    const meaning = si === -1 ? null : findingText.slice(si + sep.length)
                    return (
                      <div className="intel-cell" role="button" tabIndex={0}
                        onClick={() => setIntelModal({ target: a.target, market: a.market, sev: a.sev, finding: findingText, headline: a.headline[locale] })}
                        onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') setIntelModal({ target: a.target, market: a.market, sev: a.sev, finding: findingText, headline: a.headline[locale] }) }}
                        style={{ cursor: 'pointer' }}>
                        {meaning && (
                          <div className="intel-meaning" style={{
                            color: 'var(--accent-text)', fontSize: 11, fontWeight: 600, lineHeight: 1.5,
                            display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden',
                            marginBottom: 3,
                          }}>
                            {meaning}
                          </div>
                        )}
                        <div className="intel-technical" style={{ color: 'var(--text3)', fontSize: 10, lineHeight: 1.5,
                          fontFamily: "'JetBrains Mono', monospace",
                          display: '-webkit-box', WebkitLineClamp: meaning ? 1 : 3, WebkitBoxOrient: 'vertical', overflow: 'hidden',
                        }}>
                          {technical}
                        </div>
                        <div className="intel-hint" style={{ fontSize: 9, color: 'var(--text4)', marginTop: 2 }}>{t.trackRecord.table.intelClickHint}</div>
                      </div>
                    )
                  })()}

                  {/* Statutes */}
                  {!mobile && (() => {
                    const statutes = AUDIT_STATUTES[a.target] ?? []
                    const STATUTE_CAP = 3
                    const shown = statutes.slice(0, STATUTE_CAP)
                    const rest = statutes.slice(STATUTE_CAP)
                    return (
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 3, paddingTop: 1, minWidth: 0, overflow: 'hidden' }}>
                        {statutes.length === 0 ? (
                          <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: 'var(--text4)' }}>-</span>
                        ) : (
                          <>
                            {shown.map((s, si) => (
                              <span key={si} title={`${s.note} (${s.source})`} style={{
                                fontFamily: "'JetBrains Mono', monospace", fontSize: 8, fontWeight: 700, padding: '2px 5px',
                                borderRadius: 3, letterSpacing: '0.04em', whiteSpace: 'nowrap', cursor: 'default',
                                ...{ background: 'transparent', color: 'var(--text3)', border: '1px solid rgba(150,150,150,0.35)' },
                              }}>
                                {s.article ? `${s.law} ${s.article}` : s.law}
                              </span>
                            ))}
                            {rest.length > 0 && (
                              <span
                                title={rest.map(s => `${s.article ? `${s.law} ${s.article}` : s.law}: ${s.note} (${s.source})`).join('\n')}
                                style={{
                                  fontFamily: "'JetBrains Mono', monospace", fontSize: 8, fontWeight: 700, padding: '2px 5px',
                                  borderRadius: 3, letterSpacing: '0.04em', whiteSpace: 'nowrap', cursor: 'default',
                                  background: 'rgba(255,255,255,0.06)', color: 'var(--text3)', border: '1px solid rgba(150,150,150,0.25)',
                                }}>
                                +{rest.length}
                              </span>
                            )}
                          </>
                        )}
                      </div>
                    )
                  })()}

                  {/* Resolved */}
                  {!mobile && (
                    <div style={{ paddingTop: 1, textAlign: 'center' }}>
                      <span style={{
                        fontFamily: "'JetBrains Mono', monospace", fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 3,
                        background: 'var(--surface-sunken)', color: 'var(--text)', letterSpacing: '0.07em',
                      }}>{resolved ? t.trackRecord.row.yes : t.trackRecord.row.no}</span>
                    </div>
                  )}

                  {/* Countdown */}
                  <div style={{ paddingTop: 1 }}>
                    <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: mobile ? 12 : 16, fontWeight: 900, color: resolved ? '#00f5c4' : cdColor, lineHeight: 1.3, letterSpacing: '0.02em', fontVariantNumeric: 'tabular-nums' }}>
                      {resolved ? t.trackRecord.row.closed : cdStr}
                    </div>
                    <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 8, color: 'var(--text4)', marginTop: 2, letterSpacing: '0.06em' }}>
                      {t.trackRecord.row.disclosureLabel}
                    </div>
                  </div>

                  {/* Elapsed */}
                  {!mobile && (
                    <div style={{ paddingTop: 1 }}>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 16, fontWeight: 900, color: eColor, lineHeight: 1.3, letterSpacing: '0.02em', fontVariantNumeric: 'tabular-nums' }}>
                        {notifiedTs ? eStr : '-'}
                      </div>
                      <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 8, color: 'var(--text4)', marginTop: 2, letterSpacing: '0.06em' }}>
                        {resolved ? t.trackRecord.row.respondedLabel : t.trackRecord.row.elapsedLabel}
                      </div>
                    </div>
                  )}

                  {/* Report */}
                  {!mobile && (
                    <div style={{ paddingTop: 2 }}>
                      {meta?.reportUrl ? (
                        <button onClick={() => setReportModal(meta.reportUrl!)} style={{
                          background: 'rgba(0,245,196,0.10)', border: '1px solid rgba(0,245,196,0.3)',
                          borderRadius: 4, padding: '4px 8px', cursor: 'pointer', display: 'flex',
                          alignItems: 'center', gap: 4, color: 'var(--accent-text)', fontSize: 10, fontFamily: "'JetBrains Mono', monospace",
                          fontWeight: 700, letterSpacing: '0.06em', transition: 'background 0.15s',
                        }}>
                          <svg width="10" height="12" viewBox="0 0 10 12" fill="none"><path d="M1 1h5l3 3v7H1V1z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round"/><path d="M6 1v3h3" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round"/><path d="M3 6h4M3 8h3" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/></svg>
                          {t.trackRecord.row.pdf}
                        </button>
                      ) : (
                        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: 'var(--text4)' }}>-</span>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </div>
        </div>

        <p style={{ marginTop: 12, fontFamily: "'JetBrains Mono', monospace", fontSize: 10, color: 'var(--text4)' }}>
        {t.trackRecord.footerNote}<a href="https://github.com/rfi-irfos/android-security-audit-2026" target="_blank" rel="noopener noreferrer" style={{ color: 'var(--text3)', textDecoration: 'none' }}>github.com/rfi-irfos/android-security-audit-2026</a>
        </p>
      </div>
    </section>
  )
}
